exercise.referenceSolution:
struct Base { virtual int read() const { return 0; } virtual ~Base() = default; };
class Scaled : public Base { int value_; public: explicit Scaled(int x) : value_(x) {} int read() const override { return value_*2; } };
int solve(int a,int b) { Scaled x{a}; const Base& ref=x; return ref.read()+b; }
